  WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND id IN ('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:194');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por el art. 84 del D.228-93, Ley del Ministerio Público (nota 58 de la edición: «Artículos del 194 al 217»); cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_LOAT_OLA12.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA12')
  WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND id IN ('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:195', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:196', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:197', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:198', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:199', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:200', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:201', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:202', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:203', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:204', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:205', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:206', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:207', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:208', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:209', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:210', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:211', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:212', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:213', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:214', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:215', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:216', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:217');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'CONTEXT vigente (propuesta D5): la nota de la edición remite a la Ley de Notariado de 1930, derogada por el Código del Notariado (D.353-2005), que regula hoy esta materia; la derogación de este artículo de la LOAT no consta', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_LOAT_OLA12.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA12')
  WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND id IN ('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:233', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:234', 'OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:236');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 264 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 264)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 228 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 228)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 12 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 12)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 24 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 24)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LOAT_2007_01' GROUP BY metadata->>'estado_v';
